package com.example.domain.model.i18n

internal object DuaMl1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("ഉറക്കില്‍ നിന്ന് ഉണരുമ്പോള്‍", "മരണത്തിന് (ഉറക്കിന്) ശേഷം ഞങ്ങളെ വീണ്ടും ജീവിപ്പിച്ച അല്ലാഹുവിന് സര്‍വ്വ സ്തുതി, അവങ്കലേക്കാണ് മടക്കം.", "ഉറക്കില്‍ നിന്ന് ഉണര്‍ന്ന ഉടന്‍ അല്ലാഹുവിന് നന്ദി പറയാന്‍.", "പ്രവാചകന്‍ ﷺ ഉണര്‍ന്നാലുടന്‍ ഇത് ചൊല്ലാറുണ്ടായിരുന്നു — നന്ദിയോടെയും പരലോക സ്മരണയോടെയും ദിവസം ആരംഭിക്കല്‍."),
        "dua_leaving_home" to DuaText("വീട്ടില്‍ നിന്ന് ഇറങ്ങുമ്പോള്‍", "അല്ലാഹുവിന്‍റെ നാമത്തില്‍; ഞാന്‍ അല്ലാഹുവില്‍ ഭരമേല്‍പിച്ചു. അല്ലാഹുവല്ലാതെ ശക്തിയോ കഴിവോ ഇല്ല.", "വീട്ടില്‍ നിന്ന് പുറത്തിറങ്ങുമ്പോള്‍ അല്ലാഹുവിന്‍റെ സംരക്ഷണം തേടാന്‍.", "മലക്കുകള്‍ പറയും: നിനക്ക് മാര്‍ഗദര്‍ശനവും സംരക്ഷണവും നല്‍കപ്പെട്ടു, പിശാച് അകന്നുപോകുന്നു."),
        "dua_anxiety_distress" to DuaText("ദുഃഖത്തിനും ആശങ്കക്കുമുള്ള പ്രാര്‍ത്ഥന", "അല്ലാഹുവേ, ദുഃഖത്തില്‍ നിന്നും ആശങ്കയില്‍ നിന്നും, ദൗര്‍ബല്യത്തില്‍ നിന്നും മടിയില്‍ നിന്നും, പിശുക്കില്‍ നിന്നും ഭീരുത്വത്തില്‍ നിന്നും, കടബാധ്യതയില്‍ നിന്നും ജനങ്ങളുടെ അടിച്ചമര്‍ത്തലില്‍ നിന്നും ഞാന്‍ നിന്നോട് അഭയം തേടുന്നു.", "ദുഃഖം, ആശങ്ക, കടബാധ്യത, മാനസിക സമ്മര്‍ദ്ദം എന്നിവയുടെ സമയത്ത്.", "പ്രവാചകന്‍ ﷺ ഇത് പതിവായി ചൊല്ലിയിരുന്നു — ദുഃഖം, മടി, കടം എന്നിവയില്‍ നിന്ന് അഭയം."),
        "dua_sayyidul_istighfar" to DuaText("സയ്യിദുല്‍ ഇസ്തിഗ്ഫാര്‍", "അല്ലാഹുവേ, നീ എന്‍റെ റബ്ബാണ്, നിന്നല്ലാതെ ആരാധ്യനില്ല. നീ എന്നെ സൃഷ്ടിച്ചു, ഞാന്‍ നിന്‍റെ ദാസനാണ്. എന്‍റെ കഴിവിനൊത്ത് നിന്‍റെ ഉടമ്പടിയിലും വാഗ്ദാനത്തിലും ഞാന്‍ ഉറച്ചുനില്‍ക്കുന്നു. ഞാന്‍ ചെയ്ത തിന്മയില്‍ നിന്ന് നിന്നോട് അഭയം തേടുന്നു. എനിക്കുള്ള നിന്‍റെ അനുഗ്രഹം ഞാന്‍ അംഗീകരിക്കുന്നു, എന്‍റെ പാപവും അംഗീകരിക്കുന്നു, അതിനാല്‍ എന്നോട് പൊറുക്കേണമേ, നിന്നല്ലാതെ ആരും പാപം പൊറുക്കുകയില്ല.", "രാവിലെയും വൈകുന്നേരവും ചൊല്ലുന്നു — പ്രവാചകന്‍ ﷺ പഠിപ്പിച്ച ഏറ്റവും ശ്രേഷ്ഠമായ പശ്ചാത്താപ പ്രാര്‍ത്ഥന.", "ദൃഢവിശ്വാസത്തോടെ വൈകുന്നേരം ചൊല്ലി അന്ന് രാത്രി മരിച്ചാല്‍ സ്വര്‍ഗ്ഗത്തില്‍ പ്രവേശിക്കും; രാവിലെ ചൊല്ലിയാലും ഇതേ പ്രതിഫലം."),
        "dua_parents" to DuaText("മാതാപിതാക്കള്‍ക്കായുള്ള പ്രാര്‍ത്ഥന", "എന്‍റെ റബ്ബേ, കുട്ടിക്കാലത്ത് അവര്‍ എന്നെ വളര്‍ത്തിയതുപോലെ അവരോട് കരുണ കാണിക്കേണമേ.", "ബാല്യകാല പരിപാലനത്തിന് പ്രതിഫലമായി മാതാപിതാക്കള്‍ക്കായുള്ള ഖുര്‍ആനിക പ്രാര്‍ത്ഥന.", "മാതാപിതാക്കള്‍ക്കായി ഈ പ്രാര്‍ത്ഥന നടത്താന്‍ അല്ലാഹു തന്നെ കല്‍പിച്ചു."),
        "dua_entering_mosque" to DuaText("പള്ളിയില്‍ പ്രവേശിക്കുമ്പോള്‍", "അല്ലാഹുവേ, നിന്‍റെ കാരുണ്യത്തിന്‍റെ കവാടങ്ങള്‍ എനിക്ക് തുറന്നുതരേണമേ.", "വലതുകാല്‍ വച്ച് പള്ളിയില്‍ പ്രവേശിക്കുമ്പോള്‍ ചൊല്ലുന്നു.", "പള്ളിയില്‍ പ്രവേശിക്കുമ്പോള്‍ ഈ പ്രാര്‍ത്ഥന പ്രവാചകന്‍ ﷺ പഠിപ്പിച്ചു."),
        "dua_morning_asbahna" to DuaText("പ്രഭാത സ്മരണ", "ഞങ്ങള്‍ പ്രഭാതത്തിലെത്തി, ഈ പ്രഭാതത്തില്‍ സര്‍വ്വാധിപത്യം അല്ലാഹുവിനാണ്. സര്‍വ്വ സ്തുതിയും അല്ലാഹുവിന്. അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല, അവന്‍ ഏകനാണ്, പങ്കുകാരില്ല. അധിപത്യവും സ്തുതിയും അവനുള്ളതാണ്, അവന്‍ എല്ലാറ്റിനും കഴിവുള്ളവനാണ്.", "പ്രഭാത സമയത്ത് ചൊല്ലുന്ന സുന്നത്ത് പ്രാര്‍ത്ഥന.", "അല്ലാഹുവിന്‍റെ ആധിപത്യവും ഏകത്വവും അംഗീകരിച്ച് ദിവസം ആരംഭിക്കല്‍."),
        "dua_evening_amsayna" to DuaText("സന്ധ്യാ സ്മരണ", "ഞങ്ങള്‍ സന്ധ്യയിലെത്തി, ഈ സന്ധ്യയില്‍ സര്‍വ്വാധിപത്യം അല്ലാഹുവിനാണ്. സര്‍വ്വ സ്തുതിയും അല്ലാഹുവിന്. അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല, അവന്‍ ഏകനാണ്, പങ്കുകാരില്ല. അധിപത്യവും സ്തുതിയും അവനുള്ളതാണ്, അവന്‍ എല്ലാറ്റിനും കഴിവുള്ളവനാണ്.", "സന്ധ്യാ സമയത്ത് ചൊല്ലുന്ന സുന്നത്ത് പ്രാര്‍ത്ഥന.", "അല്ലാഹുവിന്‍റെ ആധിപത്യവും ഏകത്വവും അംഗീകരിച്ച് രാത്രി ആരംഭിക്കല്‍."),
        "dua_before_sleep" to DuaText("ഉറങ്ങുന്നതിന് മുമ്പ്", "അല്ലാഹുവേ, നിന്‍റെ നാമത്തില്‍ ഞാന്‍ മരിക്കുന്നു (ഉറങ്ങുന്നു), ജീവിക്കുന്നു (ഉണരുന്നു).", "കിടക്കയില്‍ കിടന്നതിന് ശേഷം ചൊല്ലുന്നു.", "പ്രവാചകന്‍ ﷺ ഉറങ്ങുന്നതിന് മുമ്പ് ഇത് ചൊല്ലാറുണ്ടായിരുന്നു."),
        "dua_travel" to DuaText("യാത്രാ പ്രാര്‍ത്ഥന", "ഇത് ഞങ്ങള്‍ക്ക് കീഴ്‌പ്പെടുത്തിത്തന്നവന് സ്തുതി, ഞങ്ങള്‍ക്ക് സ്വയം ഇത് കീഴ്‌പ്പെടുത്താന്‍ കഴിയുമായിരുന്നില്ല, ഞങ്ങള്‍ ഞങ്ങളുടെ റബ്ബിലേക്ക് മടങ്ങുന്നവരാണ്.", "വാഹനത്തില്‍ ഇരുന്ന് മൂന്ന് തവണ അല്ലാഹു അക്ബര്‍ ചൊല്ലിയ ശേഷം.", "സുരക്ഷയ്ക്കും അനുഗ്രഹത്തിനുമുള്ള യാത്രാ സുന്നത്ത് പ്രാര്‍ത്ഥന."),
        "dua_ayatul_kursi" to DuaText("നമസ്കാരാനന്തരം ആയത്തുല്‍ കുര്‍സി", "അല്ലാഹു — അവനല്ലാതെ ആരാധ്യനില്ല, എന്നും ജീവിക്കുന്നവന്‍, എല്ലാം നിലനിര്‍ത്തുന്നവന്‍. അവനെ മയക്കമോ ഉറക്കമോ ബാധിക്കില്ല. ആകാശങ്ങളിലും ഭൂമിയിലുമുള്ളതെല്ലാം അവന്‍റേതാണ്. അവന്‍റെ അനുമതിയില്ലാതെ അവന്‍റെയടുക്കല്‍ ശുപാര്‍ശ ചെയ്യുന്നവന്‍ ആരാണ്? അവരുടെ മുന്നിലുള്ളതും പിന്നിലുള്ളതും അവന്‍ അറിയുന്നു. അവന്‍റെ അറിവില്‍ നിന്ന് അവന്‍ ഇച്ഛിച്ചതല്ലാതെ അവര്‍ ഒന്നും ഉള്‍ക്കൊള്ളുകയില്ല. അവന്‍റെ കുര്‍സി ആകാശങ്ങളെയും ഭൂമിയെയും വ്യാപിച്ചിരിക്കുന്നു, അവയുടെ സംരക്ഷണം അവന് ക്ഷീണം വരുത്തുന്നില്ല. അവന്‍ ഉന്നതനും മഹാനുമാണ്.", "എല്ലാ നിര്‍ബന്ധ നമസ്കാരത്തിനു ശേഷവും ഉറങ്ങുന്നതിന് മുമ്പും ചൊല്ലുന്നു.", "എല്ലാ നിര്‍ബന്ധ നമസ്കാരത്തിനു ശേഷവും ഇത് ചൊല്ലുന്നവന് സ്വര്‍ഗ്ഗത്തില്‍ പ്രവേശിക്കാന്‍ മരണം മാത്രമേ തടസ്സമാകൂ; ഉറങ്ങുന്നതിന് മുമ്പ് ചൊല്ലിയാല്‍ പ്രഭാതം വരെ സംരക്ഷണം."),
        "dua_hasbunallah" to DuaText("അല്ലാഹു ഞങ്ങള്‍ക്ക് മതി", "അല്ലാഹു ഞങ്ങള്‍ക്ക് മതി, അവന്‍ ഏറ്റവും നല്ല കൈകാര്യകര്‍ത്താവാണ്.", "ശത്രുഭയം അല്ലെങ്കില്‍ വലിയ അപകടത്തിന്‍റെ സമയത്ത്.", "ഇബ്രാഹീം നബി (അ) തീയിലേക്ക് എറിയപ്പെട്ടപ്പോള്‍ ഇത് പറഞ്ഞു, പ്രവാചകന്‍ ﷺ അപകട സമയത്തും."),
        "dua_entering_home" to DuaText("വീട്ടില്‍ പ്രവേശിക്കുമ്പോള്‍", "അല്ലാഹുവിന്‍റെ നാമത്തില്‍ (ഞങ്ങള്‍ പ്രവേശിക്കുന്നു).", "വീട്ടില്‍ പ്രവേശിക്കുമ്പോള്‍ അല്ലാഹുവിന്‍റെ നാമം പറഞ്ഞ് സലാം ചൊല്ലുന്നു.", "വീട്ടില്‍ പ്രവേശിക്കുമ്പോഴും ഭക്ഷണ സമയത്തും അല്ലാഹുവിനെ സ്മരിച്ചാല്‍ പിശാച് പറയും: നിങ്ങള്‍ക്ക് ഇവിടെ രാത്രി കഴിയാനോ ഭക്ഷണം കഴിക്കാനോ ഇടമില്ല."),
        "dua_yunus" to DuaText("യൂനുസ് നബി (അ) യുടെ പ്രാര്‍ത്ഥന", "നിന്നല്ലാതെ ആരാധ്യനില്ല, നീ പരിശുദ്ധനാണ്; തീര്‍ച്ചയായും ഞാന്‍ അക്രമികളില്‍ പെട്ടവനായിരുന്നു.", "മത്സ്യത്തിന്‍റെ വയറ്റില്‍ യൂനുസ് നബി (അ) യുടെ പ്രാര്‍ത്ഥന — ഏത് പ്രയാസത്തിനും.", "ഏത് കാര്യത്തിലും ഇത് പ്രാര്‍ത്ഥിക്കുന്ന മുസ്‌ലിമിന് അല്ലാഹു ഉത്തരം നല്‍കുന്നു."),
        "dua_karb" to DuaText("കടുത്ത പ്രയാസത്തിനുള്ള പ്രാര്‍ത്ഥന", "മഹാനും സഹനശീലനുമായ അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല. മഹത്തായ സിംഹാസനത്തിന്‍റെ റബ്ബായ അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല. ആകാശങ്ങളുടെയും ഭൂമിയുടെയും ആദരണീയ സിംഹാസനത്തിന്‍റെയും റബ്ബായ അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല.", "കടുത്ത പ്രയാസത്തിന്‍റെയും ക്ലേശത്തിന്‍റെയും സമയത്ത് ചൊല്ലുന്നു.", "പ്രവാചകന്‍ ﷺ പ്രയാസ സമയത്ത് ഇത് ചൊല്ലാറുണ്ടായിരുന്നു."),
    )
}
